import{Z as e,e as a,f as n,a0 as o}from"./chunks/framework.DmpHOl9T.js";const d=JSON.parse('{"title":"Westpac PayWay","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/payments/westpac-payway.md","filePath":"integrations/payments/westpac-payway.md","lastUpdated":null}'),i={name:"integrations/payments/westpac-payway.md"};function s(r,t,l,c,h,p){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="westpac-payway" tabindex="-1">Westpac PayWay <a class="header-anchor" href="#westpac-payway" aria-label="Permalink to &quot;Westpac PayWay&quot;">​</a></h1><p>Connect Westpac PayWay to take payments through the provider configured for your form. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Payments</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Westpac PayWay</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-westpac-payway-api" tabindex="-1">Step 2. Connect to the Westpac PayWay API <a class="header-anchor" href="#step-2-connect-to-the-westpac-payway-api" aria-label="Permalink to &quot;Step 2. Connect to the Westpac PayWay API&quot;">​</a></h3><ol><li>Go to your <a href="https://www.payway.com.au/" target="_blank">PayWay account</a>.</li><li>Click on the <strong>Settings</strong> navigation item in the top-right of the main header navigation.</li><li>Click the <strong>REST API Keys</strong> link.</li><li>Click the <strong>Add</strong> button, and select <strong>Publishable</strong> as the API Key type. Click the <strong>Save</strong> button.</li><li>Copy the <strong>API Key</strong> from Westpac PayWay and paste in the <strong>Publishable Key</strong> field in Formie.</li><li>Go back and click the click the <strong>Add</strong> button, and select <strong>Secret</strong> as the API Key type. Click the <strong>Save</strong> button.</li><li>Copy the <strong>API Key</strong> from Westpac PayWay and paste in the <strong>Secret Key</strong> field in Formie.</li><li>Click on the <strong>Settings</strong> navigation item in the top-right of the main header navigation.</li><li>Click the <strong>Merchants</strong> link.</li><li>Copy the <strong>Merchant ID</strong> from Westpac PayWay and paste in the <strong>Merchant ID</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-field-setting" tabindex="-1">Step 4. Field Setting <a class="header-anchor" href="#step-4-field-setting" aria-label="Permalink to &quot;Step 4. Field Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Add a <strong>Payment</strong> field to your form.</li><li>Select Westpac PayWay for the <strong>Payment Provider</strong>.</li></ol><p>The Westpac PayWay payment integration supports only once-off payments.</p><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Complete a test payment and inspect both the saved submission and the provider’s transaction record. Confirm the amount, currency and final payment state before enabling live payments.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',14)])])}const y=e(i,[["render",s]]);export{d as __pageData,y as default};
